prog_text = '''from collections import defaultdict
import math

def components(g):
    H,W=len(g),len(g[0])
    cnt=defaultdict(int)
    for r in g:
        for v in r: cnt[v]+=1
    bg=max(cnt,key=cnt.get)
    seen=[[False]*W for _ in range(H)]; res=[]
    for y in range(H):
        for x in range(W):
            if seen[y][x] or g[y][x]==bg: continue
            c=g[y][x]; st=[(y,x)]; seen[y][x]=True; cl=[]
            while st:
                cy,cx=st.pop(); cl.append((cy,cx))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=cy+dy,cx+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True; st.append((ny,nx))
            res.append((c,cl))
    return bg,res

def skey(cl):
    ys=[y for y,x in cl]; xs=[x for y,x in cl]
    return tuple(sorted((y-min(ys),x-min(xs)) for y,x in cl))

def genuineL(cl):
    S=set(cl); ys=[y for y,x in cl]; xs=[x for y,x in cl]
    for (cy,cx) in cl:
        vcol=sorted(y for y in set(ys) if (y,cx) in S)
        hrow=sorted(x for x in set(xs) if (cy,x) in S)
        if set(cl)=={(y,cx) for y in vcol}|{(cy,x) for x in hrow} and len(vcol)>=2 and len(hrow)>=2:
            if all(vcol[i+1]-vcol[i]==1 for i in range(len(vcol)-1)) and all(hrow[i+1]-hrow[i]==1 for i in range(len(hrow)-1)):
                if (cy==vcol[0] or cy==vcol[-1]) and (cx==hrow[0] or cx==hrow[-1]):
                    return True
    return False

def mind(A,B): return min(math.dist(p,q) for p in A for q in B)

def isline(cl):
    ys=[y for y,x in cl]; xs=[x for y,x in cl]
    return len(ys)==1 or len(xs)==1 or (len(set(ys))==1 or len(set(xs))==1)

def transform(grid):
    bg,O=components(grid)
    byc=defaultdict(int)
    for c,cl in O: byc[c]+=1
    kcands=[(len(cl),c,cl) for c,cl in O if genuineL(cl) and len(cl)>1]
    _,tc,kcl=max(kcands)
    classes=defaultdict(list)
    for c,cl in O: classes[skey(cl)].append((c,cl))
    prs=[]
    for k,v in classes.items():
        if len(v)!=2 or len(k)<=1: continue
        if v[0][0]==0 and v[1][0]==0: continue
        if any(byc[c]==1 and isline(cl) for c,cl in v): continue
        prs.append((len(k),k,v))
    if not prs: return grid
    best=min(prs,key=lambda pr: min(mind(pr[2][0][1],kcl),mind(pr[2][1][1],kcl)))
    m0,m1=best[2]
    ch=m0 if mind(m0[1],kcl)>mind(m1[1],kcl) else m1
    out=[row[:] for row in grid]
    for y,x in ch[1]: out[y][x]=tc
    return out
'''
